<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { CheckCircle2, Circle, XCircle } from '@lucide/svelte'; import { cn } from '../../utils.js'; import { useTestResultsContext } from './context.svelte.js'; interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children' | 'class'> { class?: string; children?: Snippet; } let { class: className = '', children, ...rest }: Props = $props(); const results = useTestResultsContext('TestResultsSummary');</script>
